package de.legitserver.assistant.integrations.buggy;

import de.legitserver.assistant.buggy.activity.BuggyAttentionLevel;
import de.legitserver.assistant.buggy.automation.*;
import de.legitserver.assistant.buggy.repository.BuggyAutomationRepository;
import de.legitserver.assistant.core.actor.ActorId;
import de.legitserver.assistant.core.assistant.AssistantCapabilityId;
import de.legitserver.assistant.persistence.transaction.TransactionRunner;
import de.legitserver.assistant.requests.model.ApprovalRequestId;
import de.legitserver.assistant.runtime.model.ToolId;
import de.legitserver.assistant.runtime.model.ToolRiskLevel;
import java.sql.*;
import java.time.Duration;
import java.time.Instant;
import java.util.*;

public final class JdbcBuggyAutomationRepository implements BuggyAutomationRepository {
    private final TransactionRunner transactions;
    public JdbcBuggyAutomationRepository(TransactionRunner transactions){this.transactions=Objects.requireNonNull(transactions,"transactions");}
    @Override public Optional<BuggyAutomationRevision> findCurrent(String id){return transactions.readOnly(c->findCurrent(c,id));}
    @Override public List<BuggyAutomationRevision> listCurrentAutomations(int limit){if(limit<1||limit>500)throw new IllegalArgumentException("limit must be 1..500");return transactions.readOnly(c->{ArrayList<BuggyAutomationRevision> out=new ArrayList<>();try(PreparedStatement s=c.prepareStatement("SELECT r.* FROM assistant.buggy_automation_head h JOIN assistant.buggy_automation_revisions r ON r.assistant_id=h.assistant_id AND r.automation_id=h.automation_id AND r.automation_revision=h.current_revision WHERE h.assistant_id='BUGGY' ORDER BY r.changed_at DESC,r.automation_id LIMIT ?")){s.setInt(1,limit);try(ResultSet rs=s.executeQuery()){while(rs.next())out.add(map(rs));}}return List.copyOf(out);});}
    @Override public List<BuggyAutomationRevision> history(String id){return transactions.readOnly(c->{ArrayList<BuggyAutomationRevision> out=new ArrayList<>();try(PreparedStatement s=c.prepareStatement("SELECT * FROM assistant.buggy_automation_revisions WHERE assistant_id='BUGGY' AND automation_id=? ORDER BY automation_revision")){s.setString(1,id);try(ResultSet r=s.executeQuery()){while(r.next())out.add(map(r));}}return List.copyOf(out);});}
    @Override public BuggyAutomationRevision append(long expected,BuggyAutomationRevision a){Objects.requireNonNull(a,"revision");return transactions.required(c->{lock(c,a.automationId());long actual=findCurrent(c,a.automationId()).map(BuggyAutomationRevision::revision).orElse(0L);if(actual!=expected)throw new IllegalStateException("Stale automation revision");insert(c,a);if(expected==0)insertHead(c,a);else updateHead(c,expected,a);return findCurrent(c,a.automationId()).orElseThrow();});}
    @Override public List<BuggyAutomationRevision> enabledForSignal(BuggySignalType type){return transactions.readOnly(c->{ArrayList<BuggyAutomationRevision> out=new ArrayList<>();try(PreparedStatement s=c.prepareStatement("SELECT r.* FROM assistant.buggy_automation_head h JOIN assistant.buggy_automation_revisions r ON r.assistant_id=h.assistant_id AND r.automation_id=h.automation_id AND r.automation_revision=h.current_revision WHERE h.assistant_id='BUGGY' AND r.state='ENABLED' AND r.trigger_type='SIGNAL' AND r.signal_type=? ORDER BY r.automation_id")){s.setString(1,type.name());try(ResultSet rs=s.executeQuery()){while(rs.next())out.add(map(rs));}}return List.copyOf(out);});}
    @Override public List<BuggyAutomationRevision> dueScheduled(Instant at){Objects.requireNonNull(at,"at");return transactions.readOnly(c->{ArrayList<BuggyAutomationRevision> all=new ArrayList<>();try(PreparedStatement s=c.prepareStatement("SELECT r.* FROM assistant.buggy_automation_head h JOIN assistant.buggy_automation_revisions r ON r.assistant_id=h.assistant_id AND r.automation_id=h.automation_id AND r.automation_revision=h.current_revision WHERE h.assistant_id='BUGGY' AND r.state='ENABLED' AND r.trigger_type='SCHEDULE' ORDER BY r.automation_id")){try(ResultSet rs=s.executeQuery()){while(rs.next())all.add(map(rs));}}ArrayList<BuggyAutomationRevision> due=new ArrayList<>();for(BuggyAutomationRevision a:all){Instant base=latestRun(c,a.automationId()).map(BuggyAutomationRun::completedAt).orElse(a.changedAt());if(!base.plus(a.scheduleInterval()).isAfter(at))due.add(a);}return List.copyOf(due);});}
    @Override public void appendRun(BuggyAutomationRun r){Objects.requireNonNull(r,"run");transactions.required(c->{try(PreparedStatement s=c.prepareStatement("INSERT INTO assistant.buggy_automation_runs(run_id,assistant_id,automation_id,automation_revision,final_level,target_fingerprint,successful,safe_code,started_at,completed_at) VALUES (?,'BUGGY',?,?,?,?,?,?,?,?)")){s.setObject(1,r.runId());s.setString(2,r.automationId());s.setLong(3,r.automationRevision());s.setString(4,r.finalLevel().name());s.setString(5,r.targetFingerprint());s.setBoolean(6,r.successful());s.setString(7,r.safeCode());s.setTimestamp(8,Timestamp.from(r.startedAt()));s.setTimestamp(9,Timestamp.from(r.completedAt()));one(s.executeUpdate());}return null;});}
    @Override public Optional<BuggyAutomationRun> latestRun(String id){return transactions.readOnly(c->latestRun(c,id));}
    private static Optional<BuggyAutomationRun> latestRun(Connection c,String id)throws SQLException{try(PreparedStatement s=c.prepareStatement("SELECT * FROM assistant.buggy_automation_runs WHERE assistant_id='BUGGY' AND automation_id=? ORDER BY completed_at DESC,run_id DESC LIMIT 1")){s.setString(1,id);try(ResultSet r=s.executeQuery()){return r.next()?Optional.of(mapRun(r)):Optional.empty();}}}
    private static Optional<BuggyAutomationRevision> findCurrent(Connection c,String id)throws SQLException{try(PreparedStatement s=c.prepareStatement("SELECT r.* FROM assistant.buggy_automation_head h JOIN assistant.buggy_automation_revisions r ON r.assistant_id=h.assistant_id AND r.automation_id=h.automation_id AND r.automation_revision=h.current_revision WHERE h.assistant_id='BUGGY' AND h.automation_id=?")){s.setString(1,id);try(ResultSet r=s.executeQuery()){return r.next()?Optional.of(map(r)):Optional.empty();}}}
    private static void insert(Connection c,BuggyAutomationRevision a)throws SQLException{try(PreparedStatement s=c.prepareStatement("INSERT INTO assistant.buggy_automation_revisions(assistant_id,automation_id,automation_revision,previous_revision,name,state,trigger_type,signal_type,schedule_interval_seconds,max_level,attention,action_tool_id,capability_id,risk_level,max_attempts_per_target,cooldown_seconds,window_seconds,max_actions_per_window,same_target_suppression_seconds,failure_escalation_threshold,activation_request_id,changed_by,changed_at) VALUES ('BUGGY',?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)")){int i=1;s.setString(i++,a.automationId());s.setLong(i++,a.revision());if(a.previousRevision()==null)s.setObject(i++,null);else s.setLong(i++,a.previousRevision());s.setString(i++,a.name());s.setString(i++,a.state().name());s.setString(i++,a.triggerType().name());s.setString(i++,a.signalType()==null?null:a.signalType().name());if(a.scheduleInterval()==null)s.setObject(i++,null);else s.setLong(i++,a.scheduleInterval().toSeconds());s.setString(i++,a.maxLevel().name());s.setString(i++,a.attention().name());s.setString(i++,a.actionToolId().value());s.setString(i++,a.capabilityId().value());s.setString(i++,a.riskLevel().name());s.setInt(i++,a.maxAttemptsPerTarget());s.setLong(i++,a.cooldown().toSeconds());s.setLong(i++,a.window().toSeconds());s.setInt(i++,a.maxActionsPerWindow());s.setLong(i++,a.sameTargetSuppression().toSeconds());s.setInt(i++,a.failureEscalationThreshold());s.setObject(i++,a.activationRequestId()==null?null:a.activationRequestId().value());s.setString(i++,a.changedBy().value());s.setTimestamp(i,Timestamp.from(a.changedAt()));one(s.executeUpdate());}}
    private static void insertHead(Connection c,BuggyAutomationRevision a)throws SQLException{try(PreparedStatement s=c.prepareStatement("INSERT INTO assistant.buggy_automation_head(assistant_id,automation_id,current_revision,updated_at) VALUES ('BUGGY',?,?,?)")){s.setString(1,a.automationId());s.setLong(2,a.revision());s.setTimestamp(3,Timestamp.from(a.changedAt()));one(s.executeUpdate());}}
    private static void updateHead(Connection c,long expected,BuggyAutomationRevision a)throws SQLException{try(PreparedStatement s=c.prepareStatement("UPDATE assistant.buggy_automation_head SET current_revision=?,updated_at=? WHERE assistant_id='BUGGY' AND automation_id=? AND current_revision=?")){s.setLong(1,a.revision());s.setTimestamp(2,Timestamp.from(a.changedAt()));s.setString(3,a.automationId());s.setLong(4,expected);one(s.executeUpdate());}}
    private static BuggyAutomationRevision map(ResultSet r)throws SQLException{long p=r.getLong("previous_revision");Long prev=r.wasNull()?null:p;Long interval=r.getObject("schedule_interval_seconds",Long.class);UUID req=r.getObject("activation_request_id",UUID.class);return new BuggyAutomationRevision(r.getString("automation_id"),r.getLong("automation_revision"),prev,r.getString("name"),BuggyAutomationState.valueOf(r.getString("state")),BuggyAutomationTriggerType.valueOf(r.getString("trigger_type")),r.getString("signal_type")==null?null:BuggySignalType.valueOf(r.getString("signal_type")),interval==null?null:Duration.ofSeconds(interval),BuggyAutomationLevel.valueOf(r.getString("max_level")),BuggyAttentionLevel.valueOf(r.getString("attention")),new ToolId(r.getString("action_tool_id")),new AssistantCapabilityId(r.getString("capability_id")),ToolRiskLevel.valueOf(r.getString("risk_level")),r.getInt("max_attempts_per_target"),Duration.ofSeconds(r.getLong("cooldown_seconds")),Duration.ofSeconds(r.getLong("window_seconds")),r.getInt("max_actions_per_window"),Duration.ofSeconds(r.getLong("same_target_suppression_seconds")),r.getInt("failure_escalation_threshold"),req==null?null:new ApprovalRequestId(req),new ActorId(r.getString("changed_by")),r.getTimestamp("changed_at").toInstant());}
    private static BuggyAutomationRun mapRun(ResultSet r)throws SQLException{return new BuggyAutomationRun(r.getObject("run_id",UUID.class),r.getString("automation_id"),r.getLong("automation_revision"),BuggyAutomationLevel.valueOf(r.getString("final_level")),r.getString("target_fingerprint"),r.getBoolean("successful"),r.getString("safe_code"),r.getTimestamp("started_at").toInstant(),r.getTimestamp("completed_at").toInstant());}
    private static void lock(Connection c,String id)throws SQLException{long key=((long)id.hashCode()<<32)^0x4255474759423036L;try(PreparedStatement s=c.prepareStatement("SELECT pg_advisory_xact_lock(?)")){s.setLong(1,key);try(ResultSet r=s.executeQuery()){if(!r.next())throw new IllegalStateException("advisory lock failed");}}}
    private static void one(int n){if(n!=1)throw new IllegalStateException("Expected one modified row");}
}
